quests[24880] = { id = 24880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frieden für eine geschundene Seele", description = "Nehmt diesen Kristall des Lebens, und auch Eure Gefährten sollten einen nehmen. Er enthält mächtige Energien aus dem tiefgrünen Drachenschrein in der Drachenöde, und es war mein eigenes Geheimnis, um den dunklen Magien dieses Ortes so lange widerstehen zu können.\n\nWenn Ihr Sindragosa gegenübertretet, bekämpft sie, bis sie geschwächt ist, und dann sollten Eure Gefährten diese Kristalle benutzen, um die Essenz herauszulocken, die in ihr schläft. Wenn Ihr sie dann besiegt, solltet Ihr in der Lage sein, die Essenz aufzunehmen und zum Wyrmruhtempel in der Drachenöde zurückzubringen.", sourceObjective = "Benutzt die Lebenskristall, um Sindragosas Essenz zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
